const CAL_TYPES = [
  { id: "checkin", label: "Check-In", color: "#22c55e", icon: "✅" },
  { id: "coach-checkin", label: "Coach Check-In", color: "#22c55e", icon: "📹" },
  { id: "nutrition", label: "Nutrition Plan", color: "#FF9A52", icon: "🥗" },
  { id: "training", label: "Training", color: "#3b82f6", icon: "🏋️" },
  { id: "competition", label: "Competition", color: "#ef4444", icon: "🏆" },
  { id: "meal_prep", label: "Meal Prep", color: "#a855f7", icon: "🍱" },
  { id: "reminder", label: "Reminder", color: "#f59e0b", icon: "🔔" },
];

const _todayBase = new Date();
const _pad = (n) => String(n).padStart(2, "0");
const _ds = (y, m, d) => `${y}-${_pad(m + 1)}-${_pad(d)}`;

const SEED_EVENTS = [];
;

// ── Barcode Camera Scanner ────────────────────────────────────────────────────
// Uses html5-qrcode loaded dynamically from CDN. Designed so a Capacitor
// ML Kit native scanner can later replace just the contents of this component
// without changing how callers use it.
//
// Props:
//   onDetected(code) — called with the scanned barcode string
//   onClose()        — called when user dismisses the scanner

// Preload the scanner library in the background so it is already cached in
// memory by the time the user opens the scanner. Removes the "Starting camera…"
// network delay on first use. Safe to call multiple times.
function preloadBarcodeLib() {
  try {
    if (typeof window === "undefined") return;
    if (window.Html5Qrcode) return;
    if (document.querySelector("script[data-html5qrcode]")) return;
    const s = document.createElement("script");
    s.src = "https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js";
    s.async = true;
    s.dataset.html5qrcode = "1";
    document.head.appendChild(s);
  } catch (_) {}
}

function BarcodeCameraScanner({ onDetected, onClose }) {
  const containerRef = useRef(null);
  const scannerRef = useRef(null);
  const detectedRef = useRef(false);
  const [status, setStatus] = useState("loading"); // loading | scanning | error
  const [error, setError] = useState("");
  const [isNative, setIsNative] = useState(false);
  const [diag, setDiag] = useState(""); // temporary on-screen diagnostic
  const [stuck, setStuck] = useState(false); // watchdog: overlay outlived its scan

  // Safety net: if the native scanner has handed back control but this overlay
  // is somehow still mounted, surface a way out instead of a blank screen.
  useEffect(() => {
    if (!isNative) return;
    const t = setTimeout(() => {
      if (!detectedRef.current) setStuck(true);
    }, 12000);
    return () => clearTimeout(t);
  }, [isNative]);

  // ── NATIVE PATH (Capacitor app): use ML Kit's native scanner ────────────────
  // On a real device we use @capacitor-mlkit/barcode-scanning, which is
  // hardware-accelerated (Apple Vision / Google ML Kit) and dramatically faster
  // and more reliable than the JS web scanner. In a plain browser this import
  // does nothing and we fall through to the web scanner below.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      // Detect the native app via the global Capacitor runtime (present only
      // inside the app shell). Using the global avoids importing @capacitor/core,
      // which is externalised for the web build and would fail to resolve here.
      const cap = (typeof window !== "undefined") ? window.Capacitor : undefined;
      const native = !!(cap && typeof cap.isNativePlatform === "function" && cap.isNativePlatform());
      // TEMP diagnostic — shows what the device actually reports.
      try {
        const hasCap = !!cap;
        const hasFn = !!(cap && typeof cap.isNativePlatform === "function");
        const plat = cap && cap.getPlatform ? cap.getPlatform() : "n/a";
        setDiag(`cap=${hasCap} fn=${hasFn} native=${native} platform=${plat}`);
      } catch (e) { setDiag("diag-error: " + ((e && e.message) || e)); }
      if (!native) return; // browser — web scanner path handles it
      if (cancelled) return;
      setIsNative(true);

      let BarcodeScanner;
      try {
        const capRT = (typeof window !== "undefined") ? window.Capacitor : undefined;
        BarcodeScanner = capRT && capRT.Plugins && capRT.Plugins.BarcodeScanner;
        if (!BarcodeScanner) throw new Error("plugin unavailable");
      } catch (e) {
        setError("Scanner module unavailable. Please update the app.");
        setStatus("error");
        return;
      }

      try {
        // Make sure the on-device ML Kit module is ready (Android downloads it
        // once on first use; iOS has it built in).
        try {
          const avail = await BarcodeScanner.isGoogleBarcodeScannerModuleAvailable();
          if (avail && avail.available === false) {
            await BarcodeScanner.installGoogleBarcodeScannerModule();
          }
        } catch (_) {}

        // Request camera permission.
        const perm = await BarcodeScanner.requestPermissions();
        if (cancelled) return;
        if (perm?.camera !== "granted" && perm?.camera !== "limited") {
          setError("Camera permission was denied. Enable camera access in Settings and try again.");
          setStatus("error");
          return;
        }

        setStatus("scanning");

        // Open the native full-screen scanner UI and wait for a result.
        const { barcodes } = await BarcodeScanner.scan();

        // NOTE: deliberately NOT gated on `cancelled` here. The native scanner
        // has already returned a real result, and if this effect instance was
        // superseded by a re-render, bailing out would leave the overlay
        // mounted over an empty view with no way forward but Cancel.
        // detectedRef guards against handling the same scan twice.
        const raw = barcodes && barcodes.length ? barcodes[0].rawValue : "";
        const clean = String(raw || "").replace(/\D/g, "");
        if (detectedRef.current) return;
        if (clean.length >= 8) {
          detectedRef.current = true;
          onDetected(clean);
        } else {
          // User closed the native scanner without scanning, or scanned a
          // non-product code — just close back to the picker.
          detectedRef.current = true;
          onClose();
        }
      } catch (e) {
        const msg = (e && e.message) || String(e);
        if (detectedRef.current) return;
        if (/cancel/i.test(msg)) {
          detectedRef.current = true;
          onClose(); // user backed out of the native scanner
        } else if (!cancelled) {
          setError("Could not start the scanner. Please try again.");
          setStatus("error");
        } else {
          // Superseded instance that errored — close rather than hang.
          onClose();
        }
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Load html5-qrcode from CDN if not already loaded
  const ensureLib = () => new Promise((resolve, reject) => {
    if (window.Html5Qrcode) return resolve(window.Html5Qrcode);
    const existing = document.querySelector('script[data-html5qrcode]');
    if (existing) {
      existing.addEventListener("load", () => resolve(window.Html5Qrcode));
      existing.addEventListener("error", () => reject(new Error("Could not load scanner library")));
      return;
    }
    const s = document.createElement("script");
    s.src = "https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js";
    s.async = true;
    s.dataset.html5qrcode = "1";
    s.onload = () => resolve(window.Html5Qrcode);
    s.onerror = () => reject(new Error("Could not load scanner library — check your connection"));
    document.head.appendChild(s);
  });

  useEffect(() => {
    let cancelled = false;
    let instance = null;

    (async () => {
      // Skip the web scanner entirely on native — the ML Kit effect handles it.
      const cap = (typeof window !== "undefined") ? window.Capacitor : undefined;
      if (cap && typeof cap.isNativePlatform === "function" && cap.isNativePlatform()) return;

      try {
        const Html5Qrcode = await ensureLib();
        if (cancelled) return;

        // Wait one tick so the container div is mounted
        await new Promise((r) => setTimeout(r, 50));
        if (cancelled || !containerRef.current) return;

        instance = new Html5Qrcode(containerRef.current.id);
        scannerRef.current = instance;

        const config = {
          // Higher fps = the decoder analyses far more frames per second,
          // so it locks onto a barcode much faster.
          fps: 25,
          qrbox: (vw, vh) => {
            const minEdge = Math.min(vw, vh);
            const w = Math.floor(minEdge * 0.85);
            const h = Math.floor(w * 0.45); // wide rectangle for 1D barcodes
            return { width: w, height: h };
          },
          aspectRatio: 1.7,
          // Decode 1D supermarket barcodes + QR
          formatsToSupport: [
            0,  // QR_CODE
            8,  // EAN_13
            9,  // EAN_8
            14, // UPC_A
            15, // UPC_E
            10, // CODE_128
            11, // CODE_39
            13, // ITF
          ],
          // Use the browser/OS-native BarcodeDetector when available — it is
          // hardware-accelerated and dramatically faster than JS decoding.
          experimentalFeatures: { useBarCodeDetectorIfSupported: true },
          rememberLastUsedCamera: true,
        };

        await instance.start(
          // Simple, known-good rear-camera request. Do NOT add a `focusMode`
          // constraint — the iOS WebView rejects it and the camera fails to
          // start (black screen + "camera unavailable").
          { facingMode: "environment" },
          config,
          (decodedText) => {
            if (detectedRef.current) return;
            const clean = String(decodedText || "").replace(/\D/g, "");
            if (clean.length < 8) return;
            detectedRef.current = true;
            // Stop in the background — don't make caller wait
            try { instance.stop().then(() => instance.clear()).catch(() => {}); } catch {}
            onDetected(clean);
          },
          () => { /* per-frame failures are normal — ignore */ }
        ).catch(async (err) => {
          // Some devices reject detailed constraints — fall back to simplest
          try {
            await instance.start(
              { facingMode: "environment" },
              config,
              (decodedText) => {
                if (detectedRef.current) return;
                const clean = String(decodedText || "").replace(/\D/g, "");
                if (clean.length < 8) return;
                detectedRef.current = true;
                try { instance.stop().then(() => instance.clear()).catch(() => {}); } catch {}
                onDetected(clean);
              },
              () => {}
            );
          } catch (innerErr) {
            throw innerErr;
          }
        });

        if (!cancelled) setStatus("scanning");
      } catch (e) {
        if (cancelled) return;
        const msg = (e && e.message) || String(e);
        let friendly = msg;
        if (/Permission|NotAllowed|denied/i.test(msg)) {
          friendly = "Camera permission was denied. Allow camera access in your browser settings and try again.";
        } else if (/NotFound|no camera|not available/i.test(msg)) {
          friendly = "No camera available on this device.";
        } else if (/secure|https/i.test(msg)) {
          friendly = "Camera requires a secure HTTPS connection.";
        }
        setError(friendly);
        setStatus("error");
      }
    })();

    return () => {
      cancelled = true;
      const inst = scannerRef.current;
      if (inst) {
        try {
          inst.stop().then(() => { try { inst.clear(); } catch {} }).catch(() => {});
        } catch {}
      }
    };
  }, []);

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.92)",
        display: "flex", alignItems: "center", justifyContent: "center",
        zIndex: 2000, padding: 20,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "min(560px, 100%)", background: T.surface,
          border: `1px solid ${T.border}`, borderRadius: 16, overflow: "hidden",
          display: "flex", flexDirection: "column",
        }}
      >
        <div style={{ padding: "14px 18px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ fontFamily: "Bebas Neue", fontSize: 16, letterSpacing: 2, color: T.text }}>
            📷 SCAN BARCODE
          </div>
          <button
            onClick={onClose}
            style={{ background: "none", border: "none", color: T.muted, fontSize: 22, cursor: "pointer", lineHeight: 1 }}
            aria-label="Close scanner"
          >×</button>
        </div>
        {diag && (
          <div style={{ padding: "6px 12px", background: "#222", color: "#9ae6b4", fontFamily: "monospace", fontSize: 10, wordBreak: "break-all" }}>
            {diag}
          </div>
        )}
        <div style={{ position: "relative", background: "#000", aspectRatio: "4/3" }}>
          <div
            id="nrn-barcode-reader"
            ref={containerRef}
            style={{ width: "100%", height: "100%", overflow: "hidden" }}
          />
          {status === "loading" && (
            <div style={{
              position: "absolute", inset: 0, display: "flex", alignItems: "center",
              justifyContent: "center", color: T.muted, fontFamily: "DM Sans", fontSize: 13,
            }}>Starting camera…</div>
          )}
          {stuck && (
            <button
              onClick={() => { detectedRef.current = true; onClose(); }}
              style={{
                width: "100%", padding: "14px", marginBottom: 10,
                background: T.accent, color: T.bg, border: "none", borderRadius: 12,
                fontFamily: "Bebas Neue", fontSize: 16, letterSpacing: 2, cursor: "pointer",
              }}
              type="button"
            >
              DONE
            </button>
          )}
          {status === "error" && (
            <div style={{
              position: "absolute", inset: 0, display: "flex", flexDirection: "column",
              alignItems: "center", justifyContent: "center", padding: 20,
              color: T.danger, fontFamily: "DM Sans", fontSize: 13, textAlign: "center", gap: 8,
            }}>
              <div style={{ fontSize: 32 }}>⚠️</div>
              <div>{error}</div>
            </div>
          )}
        </div>
        <div style={{ padding: "12px 18px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
          <div style={{ fontFamily: "DM Sans", fontSize: 11, color: T.muted, flex: 1 }}>
            {stuck
              ? "Scan finished — tap Done to see the result."
              : status === "scanning"
                ? "Centre the barcode in the frame"
                : ""}
          </div>
          <button
            onClick={onClose}
            style={{
              background: T.card, color: T.text, border: `1px solid ${T.border}`,
              borderRadius: 8, padding: "8px 16px", fontFamily: "Bebas Neue",
              fontSize: 13, letterSpacing: 1, cursor: "pointer",
            }}
          >CLOSE</button>
        </div>
      </div>
    </div>
  );
}

// ── Mini Calendar ─────────────────────────────────────────────────────────────
function MiniCalendar({ events, setEvents, profileId }) {
  const today = new Date();
  const todayStr = _ds(today.getFullYear(), today.getMonth(), today.getDate());

  const [viewing, setViewing] = useState({
    year: today.getFullYear(),
    month: today.getMonth(),
  });
  const [showModal, setShowModal] = useState(false);
  const [editEvent, setEditEvent] = useState(null);
  const [inviteEvent, setInviteEvent] = useState(null); // read-only coach check-in invite view
  const [selectedDate, setSelectedDate] = useState(null);
  const [form, setForm] = useState({
    title: "",
    type: "checkin",
    date: "",
    note: "",
  });

  const monthNames = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const dayNames = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

  const firstDay = new Date(viewing.year, viewing.month, 1).getDay();
  const daysInMonth = new Date(viewing.year, viewing.month + 1, 0).getDate();

  const prevMonth = () =>
    setViewing((v) => ({
      year: v.month === 0 ? v.year - 1 : v.year,
      month: v.month === 0 ? 11 : v.month - 1,
    }));
  const nextMonth = () =>
    setViewing((v) => ({
      year: v.month === 11 ? v.year + 1 : v.year,
      month: v.month === 11 ? 0 : v.month + 1,
    }));

  const cells = [];
  for (let i = 0; i < firstDay; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const eventsOn = (ds) => events.filter((e) => e.date === ds);
  const getType = (id) => CAL_TYPES.find((t) => t.id === id) || CAL_TYPES[0];

  const openNew = (ds) => {
    setEditEvent(null);
    setForm({ title: "", type: "checkin", date: ds || todayStr, note: "" });
    setShowModal(true);
  };
  const openEdit = (ev, e) => {
    e.stopPropagation();
    // Coach check-ins and coach-created events are read-only: open the viewer.
    if (ev.type === "coach-checkin" || ev.readOnly || ev.coachCreated) {
      setInviteEvent(ev);
      return;
    }
    setEditEvent(ev);
    setForm({
      title: ev.title,
      type: ev.type,
      date: ev.date,
      note: ev.note || ev.notes || "",
    });
    setShowModal(true);
  };
  const save = async () => {
    if (!form.title.trim()) return;
    if (editEvent) {
      // For edits, delete old and create new (simple approach)
      if (profileId) {
        try { await apiFetch(`/calendar-events/${profileId}/${editEvent.id}`, { method: 'DELETE' }); } catch {}
      }
      setEvents((evs) =>
        evs.filter((e) => e.id !== editEvent.id)
      );
    }
    // Create new event
    if (profileId) {
      try {
        const created = await apiFetch(`/calendar-events/${profileId}`, {
          method: 'POST',
          body: JSON.stringify({
            date: form.date,
            title: form.title,
            startISO: form.date,
            endISO: form.date,
            notes: form.note || '',
          }),
        });
        setEvents((evs) => [...evs, { id: created.id, date: created.date, title: created.title, notes: created.notes, type: form.type }]);
      } catch (e) {
        // Fallback to local
        setEvents((evs) => [...evs, { id: Date.now(), ...form }]);
      }
    } else {
      setEvents((evs) => [...evs, { id: Date.now(), ...form }]);
    }
    setShowModal(false);
  };
  const remove = async () => {
    if (profileId && editEvent?.id) {
      try { await apiFetch(`/calendar-events/${profileId}/${editEvent.id}`, { method: 'DELETE' }); } catch {}
    }
    setEvents((evs) => evs.filter((e) => e.id !== editEvent.id));
    setShowModal(false);
  };

  // Upcoming: next 5 events from today
  const upcoming = [...events]
    .filter((e) => e.date >= todayStr)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(0, 5);

  // Build a downloadable .ics so the athlete can add the check-in to their
  // own device calendar (iOS/Android both open .ics natively).
  const addInviteToDeviceCalendar = (ev) => {
    if (!ev) return;
    const dt = String(ev.date).replace(/-/g, ""); // YYYYMMDD
    let dtStart, dtEnd;
    if (ev.time) {
      const hhmm = String(ev.time).replace(":", "").slice(0, 4).padEnd(4, "0");
      dtStart = `${dt}T${hhmm}00`;
      // default 30-minute duration
      let h = parseInt(hhmm.slice(0, 2), 10);
      let m = parseInt(hhmm.slice(2, 4), 10) + 30;
      if (m >= 60) { m -= 60; h = (h + 1) % 24; }
      dtEnd = `${dt}T${_pad(h)}${_pad(m)}00`;
    } else {
      dtStart = dt;
      dtEnd = dt;
    }
    const esc = (s) => String(s || "").replace(/([,;\\])/g, "\\$1").replace(/\n/g, "\\n");
    const descParts = [];
    if (ev.notes) descParts.push(ev.notes);
    if (ev.linkUrl) descParts.push(`Join: ${ev.linkUrl}`);
    const ics = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//No Rule Nutrition//Check-in//EN",
      "BEGIN:VEVENT",
      `UID:nrn-${ev.id}@norulenutrition.uk`,
      ev.time ? `DTSTART:${dtStart}` : `DTSTART;VALUE=DATE:${dtStart}`,
      ev.time ? `DTEND:${dtEnd}` : `DTEND;VALUE=DATE:${dtEnd}`,
      `SUMMARY:${esc(ev.title || "Coach check-in")}`,
      descParts.length ? `DESCRIPTION:${esc(descParts.join("\n\n"))}` : "",
      ev.linkUrl ? `LOCATION:${esc(ev.linkUrl)}` : "",
      "END:VEVENT",
      "END:VCALENDAR",
    ].filter(Boolean).join("\r\n");
    try {
      const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `checkin-${ev.date}.ics`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (_) {
      // Fallback: open the link directly if file creation fails
      if (ev.linkUrl) window.open(ev.linkUrl, "_blank");
    }
  };

  return (
    <>
      {/* ── Coach Check-in Invite (read-only) ── */}
      {inviteEvent && (
        <div
          onClick={() => setInviteEvent(null)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.6)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
            padding: 20,
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              background: T.card,
              border: `1px solid ${T.border}`,
              borderRadius: 16,
              padding: 22,
              maxWidth: 380,
              width: "100%",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
              <span style={{ fontSize: 20 }}>{inviteEvent.type === "coach-checkin" ? "📹" : "📅"}</span>
              <span style={{ fontFamily: "Bebas Neue", fontSize: 12, letterSpacing: 2, color: T.coachGreen }}>
                {inviteEvent.type === "coach-checkin" ? "COACH CHECK-IN" : "FROM YOUR COACH"}
              </span>
            </div>
            <div style={{ fontFamily: "Bebas Neue", fontSize: 22, letterSpacing: 1, color: T.text, marginBottom: 8 }}>
              {inviteEvent.title}
            </div>
            <div style={{ fontFamily: "JetBrains Mono", fontSize: 13, color: T.accent, marginBottom: 14 }}>
              {new Date(inviteEvent.date + "T00:00:00").toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long" })}
              {(() => {
                if (inviteEvent.time) return ` · ${inviteEvent.time}`;
                // Derive a time from startISO when present (coach calendar events)
                try {
                  if (inviteEvent.startISO && String(inviteEvent.startISO).length > 10) {
                    const t = new Date(inviteEvent.startISO).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
                    return ` · ${t}`;
                  }
                } catch {}
                return "";
              })()}
            </div>
            {inviteEvent.notes && (
              <div style={{ fontFamily: "DM Sans", fontSize: 13, color: T.text, lineHeight: 1.6, whiteSpace: "pre-wrap", marginBottom: 16 }}>
                {inviteEvent.notes}
              </div>
            )}
            {inviteEvent.linkUrl && (
              <a
                href={inviteEvent.linkUrl}
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  display: "block",
                  textAlign: "center",
                  background: T.coachGreen,
                  color: "#06210f",
                  fontFamily: "Bebas Neue",
                  fontSize: 15,
                  letterSpacing: 1.5,
                  textDecoration: "none",
                  padding: "12px",
                  borderRadius: 10,
                  marginBottom: 10,
                }}
              >
                📹 JOIN GOOGLE MEET
              </a>
            )}
            <button
              onClick={() => addInviteToDeviceCalendar(inviteEvent)}
              style={{
                width: "100%",
                background: T.surface,
                color: T.text,
                border: `1px solid ${T.border}`,
                borderRadius: 10,
                padding: "11px",
                fontFamily: "DM Sans",
                fontSize: 13,
                cursor: "pointer",
                marginBottom: 8,
              }}
            >
              📅 Add to my device calendar
            </button>
            <button
              onClick={() => setInviteEvent(null)}
              style={{
                width: "100%",
                background: "none",
                color: T.muted,
                border: "none",
                padding: "8px",
                fontFamily: "DM Sans",
                fontSize: 12,
                cursor: "pointer",
              }}
            >
              Close
            </button>
          </div>
        </div>
      )}

      {/* ── Event Modal ── */}
      {showModal && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "#000000d0",
            zIndex: 500,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
          onClick={(e) => {
            if (e.target === e.currentTarget) setShowModal(false);
          }}
        >
          <div
            style={{
              background: T.card,
              border: `1px solid ${T.accent}55`,
              borderRadius: 20,
              padding: 28,
              width: "100%",
              maxWidth: 420,
              animation: "fadeUp .2s ease",
            }}
          >
            <div
              style={{
                fontFamily: "Bebas Neue",
                fontSize: 20,
                letterSpacing: 2,
                color: T.text,
                marginBottom: 20,
              }}
            >
              {editEvent ? "EDIT EVENT" : "ADD EVENT"}
            </div>

            {/* Title */}
            <div style={{ marginBottom: 12 }}>
              <label
                style={{
                  fontFamily: "DM Sans",
                  fontSize: 10,
                  color: T.muted,
                  letterSpacing: 1,
                  textTransform: "uppercase",
                  display: "block",
                  marginBottom: 5,
                }}
              >
                Title *
              </label>
              <input
                value={form.title}
                onChange={(e) =>
                  setForm((f) => ({ ...f, title: e.target.value }))
                }
                placeholder="e.g. Weekly Check-In"
                style={{
                  width: "100%",
                  background: T.surface,
                  border: `1px solid ${T.border}`,
                  borderRadius: 10,
                  padding: "10px 12px",
                  color: T.text,
                  fontFamily: "DM Sans",
                  fontSize: 13,
                  outline: "none",
                }}
              />
            </div>

            {/* Date + Type */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 10,
                marginBottom: 12,
              }}
            >
              <div>
                <label
                  style={{
                    fontFamily: "DM Sans",
                    fontSize: 10,
                    color: T.muted,
                    letterSpacing: 1,
                    textTransform: "uppercase",
                    display: "block",
                    marginBottom: 5,
                  }}
                >
                  Date *
                </label>
                <input
                  type="date"
                  value={form.date}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, date: e.target.value }))
                  }
                  style={{
                    width: "100%",
                    background: T.surface,
                    border: `1px solid ${T.border}`,
                    borderRadius: 10,
                    padding: "10px 12px",
                    color: T.text,
                    fontFamily: "DM Sans",
                    fontSize: 13,
                    outline: "none",
                    colorScheme: "dark",
                  }}
                />
              </div>
              <div>
                <label
                  style={{
                    fontFamily: "DM Sans",
                    fontSize: 10,
                    color: T.muted,
                    letterSpacing: 1,
                    textTransform: "uppercase",
                    display: "block",
                    marginBottom: 5,
                  }}
                >
                  Type
                </label>
                <select
                  value={form.type}
                  onChange={(e) =>
                    setForm((f) => ({ ...f, type: e.target.value }))
                  }
                  style={{
                    width: "100%",
                    background: T.surface,
                    border: `1px solid ${T.border}`,
                    borderRadius: 10,
                    padding: "10px 12px",
                    color: T.text,
                    fontFamily: "DM Sans",
                    fontSize: 13,
                    outline: "none",
                  }}
                >
                  {CAL_TYPES.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.icon} {t.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Note */}
            <div style={{ marginBottom: 18 }}>
              <label
                style={{
                  fontFamily: "DM Sans",
                  fontSize: 10,
                  color: T.muted,
                  letterSpacing: 1,
                  textTransform: "uppercase",
                  display: "block",
                  marginBottom: 5,
                }}
              >
                Note
              </label>
              <textarea
                value={form.note}
                onChange={(e) =>
                  setForm((f) => ({ ...f, note: e.target.value }))
                }
                placeholder="Optional details or reminders…"
                style={{
                  width: "100%",
                  background: T.surface,
                  border: `1px solid ${T.border}`,
                  borderRadius: 10,
                  padding: "10px 12px",
                  color: T.text,
                  fontFamily: "DM Sans",
                  fontSize: 13,
                  outline: "none",
                  resize: "vertical",
                  minHeight: 64,
                }}
              />
            </div>

            {/* Type preview */}
            {(() => {
              const t = getType(form.type);
              return (
                <div style={{ marginBottom: 16 }}>
                  <span
                    style={{
                      fontFamily: "DM Sans",
                      fontSize: 11,
                      fontWeight: 600,
                      padding: "3px 10px",
                      borderRadius: 99,
                      background: `${t.color}22`,
                      color: t.color,
                      border: `1px solid ${t.color}44`,
                    }}
                  >
                    {t.icon} {t.label}
                  </span>
                </div>
              );
            })()}

            <div style={{ display: "flex", gap: 8 }}>
              {editEvent && (
                <button
                  onClick={remove}
                  style={{
                    background: `${T.danger}18`,
                    border: `1px solid ${T.danger}44`,
                    borderRadius: 10,
                    padding: "10px 14px",
                    color: T.danger,
                    fontFamily: "DM Sans",
                    fontSize: 12,
                    cursor: "pointer",
                  }}
                >
                  🗑 Delete
                </button>
              )}
              <button
                onClick={() => setShowModal(false)}
                style={{
                  flex: 1,
                  background: "none",
                  border: `1px solid ${T.border}`,
                  borderRadius: 10,
                  padding: 10,
                  color: T.muted,
                  fontFamily: "DM Sans",
                  fontSize: 13,
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>
              <button
                onClick={save}
                disabled={!form.title.trim()}
                style={{
                  flex: 2,
                  background: form.title.trim() ? T.accent : T.border,
                  color: form.title.trim() ? T.bg : T.muted,
                  border: "none",
                  borderRadius: 10,
                  padding: 10,
                  fontFamily: "Bebas Neue",
                  fontSize: 15,
                  letterSpacing: 1.5,
                  cursor: form.title.trim() ? "pointer" : "default",
                  transition: "all .2s",
                }}
              >
                {editEvent ? "SAVE CHANGES" : "ADD EVENT"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Calendar card ── */}
      <div
        style={{
          background: T.card,
          border: `1px solid ${T.border}`,
          borderRadius: 16,
          padding: 20,
          position: "relative",
        }}
      >
        {/* Header */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 14,
          }}
        >
          <button
            onClick={prevMonth}
            style={{
              background: "none",
              border: `1px solid ${T.border}`,
              color: T.muted,
              borderRadius: 8,
              width: 28,
              height: 28,
              cursor: "pointer",
              fontSize: 13,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "all .15s",
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = T.accent;
              e.currentTarget.style.color = T.accent;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = T.border;
              e.currentTarget.style.color = T.muted;
            }}
          >
            ‹
          </button>
          <div
            style={{
              fontFamily: "Bebas Neue",
              fontSize: 16,
              letterSpacing: 2,
              color: T.text,
            }}
          >
            {monthNames[viewing.month]}{" "}
            <span style={{ color: T.accent }}>{viewing.year}</span>
          </div>
          <button
            onClick={nextMonth}
            style={{
              background: "none",
              border: `1px solid ${T.border}`,
              color: T.muted,
              borderRadius: 8,
              width: 28,
              height: 28,
              cursor: "pointer",
              fontSize: 13,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "all .15s",
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = T.accent;
              e.currentTarget.style.color = T.accent;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = T.border;
              e.currentTarget.style.color = T.muted;
            }}
          >
            ›
          </button>
        </div>

        {/* Day headers */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(7,1fr)",
            gap: 1,
            marginBottom: 4,
          }}
        >
          {dayNames.map((d) => (
            <div
              key={d}
              style={{
                textAlign: "center",
                fontFamily: "DM Sans",
                fontSize: 9,
                color: T.muted,
                padding: "2px 0",
                letterSpacing: 0.5,
              }}
            >
              {d}
            </div>
          ))}
        </div>

        {/* Day cells */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(7,1fr)",
            gap: 1,
          }}
        >
          {cells.map((d, i) => {
            if (!d) return <div key={`e${i}`} style={{ minHeight: 36 }} />;
            const ds = _ds(viewing.year, viewing.month, d);
            const isToday = ds === todayStr;
            const dayEvs = eventsOn(ds);
            const hasEv = dayEvs.length > 0;
            return (
              <div
                key={d}
                onClick={() => {
                  setSelectedDate(ds);
                  openNew(ds);
                }}
                style={{
                  minHeight: 36,
                  borderRadius: 7,
                  cursor: "pointer",
                  padding: "4px 2px",
                  background: isToday
                    ? T.accent
                    : selectedDate === ds
                    ? `${T.accent}18`
                    : "none",
                  border: isToday
                    ? "none"
                    : hasEv
                    ? `1px solid ${getType(dayEvs[0].type).color}55`
                    : "1px solid transparent",
                  position: "relative",
                  transition: "background .12s",
                }}
                onMouseEnter={(e) => {
                  if (!isToday)
                    e.currentTarget.style.background = `${T.accent}12`;
                }}
                onMouseLeave={(e) => {
                  if (!isToday)
                    e.currentTarget.style.background =
                      selectedDate === ds ? `${T.accent}18` : "none";
                }}
              >
                <div
                  style={{
                    textAlign: "center",
                    fontFamily: "JetBrains Mono",
                    fontSize: 11,
                    color: isToday ? T.bg : T.text,
                    fontWeight: isToday ? 700 : 400,
                  }}
                >
                  {d}
                </div>
                {/* Event dots */}
                {dayEvs.length > 0 && (
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "center",
                      gap: 2,
                      marginTop: 2,
                      flexWrap: "wrap",
                    }}
                  >
                    {dayEvs.slice(0, 3).map((ev, ei) => (
                      <div
                        key={ei}
                        onClick={(e) => openEdit(ev, e)}
                        style={{
                          width: 5,
                          height: 5,
                          borderRadius: "50%",
                          background: getType(ev.type).color,
                          cursor: "pointer",
                          flexShrink: 0,
                        }}
                        title={ev.title}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Upcoming strip */}
        {upcoming.length > 0 && (
          <div
            style={{
              marginTop: 14,
              paddingTop: 12,
              borderTop: `1px solid ${T.border}`,
            }}
          >
            <div
              style={{
                fontFamily: "Bebas Neue",
                fontSize: 11,
                letterSpacing: 1.5,
                color: T.muted,
                marginBottom: 8,
              }}
            >
              UPCOMING
            </div>
            {upcoming.map((ev) => {
              const t = getType(ev.type);
              const d = new Date(ev.date + "T00:00:00");
              const diff = Math.round((d - today) / 86400000);
              const when =
                diff === 0
                  ? "Today"
                  : diff === 1
                  ? "Tomorrow"
                  : `${d.toLocaleDateString("en-GB", {
                      day: "numeric",
                      month: "short",
                    })}`;
              return (
                <div
                  key={ev.id}
                  onClick={(e) => openEdit(ev, e)}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    padding: "5px 6px",
                    borderRadius: 8,
                    cursor: "pointer",
                    marginBottom: 3,
                    transition: "background .12s",
                  }}
                  onMouseEnter={(e) =>
                    (e.currentTarget.style.background = T.surface)
                  }
                  onMouseLeave={(e) =>
                    (e.currentTarget.style.background = "transparent")
                  }
                >
                  <div
                    style={{
                      width: 7,
                      height: 7,
                      borderRadius: "50%",
                      background: t.color,
                      flexShrink: 0,
                    }}
                  />
                  <div
                    style={{
                      flex: 1,
                      fontFamily: "DM Sans",
                      fontSize: 11,
                      color: T.text,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {ev.title}
                  </div>
                  <div
                    style={{
                      fontFamily: "JetBrains Mono",
                      fontSize: 9,
                      color:
                        diff <= 1 ? T.danger : diff <= 3 ? T.accent : T.muted,
                      flexShrink: 0,
                    }}
                  >
                    {when}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Legend */}
        <div
          style={{
            display: "flex",
            gap: 10,
            marginTop: 12,
            paddingTop: 10,
            borderTop: `1px solid ${T.border}`,
            flexWrap: "wrap",
          }}
        >
          {[
            { color: T.accent, label: "Today", square: true },
            { color: T.coachGreen, label: "Check-In" },
            { color: "#3b82f6", label: "Training" },
            { color: "#ef4444", label: "Event" },
          ].map((l) => (
            <div
              key={l.label}
              style={{ display: "flex", alignItems: "center", gap: 4 }}
            >
              <div
                style={{
                  width: l.square ? 8 : 6,
                  height: l.square ? 8 : 6,
                  borderRadius: l.square ? 2 : "50%",
                  background: l.color,
                }}
              />
              <span
                style={{ fontFamily: "DM Sans", fontSize: 9, color: T.muted }}
              >
                {l.label}
              </span>
            </div>
          ))}
        </div>

        {/* ── Floating + button ── */}
        <button
          onClick={() => openNew(todayStr)}
          title="Add event"
          style={{
            position: "absolute",
            bottom: 16,
            right: 16,
            width: 36,
            height: 36,
            borderRadius: "50%",
            background: T.accent,
            border: "none",
            color: T.bg,
            fontSize: 22,
            fontWeight: 300,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
            boxShadow: `0 4px 16px ${T.accent}55`,
            transition: "all .2s",
            zIndex: 10,
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = "scale(1.12)";
            e.currentTarget.style.boxShadow = `0 6px 24px ${T.accent}77`;
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = "scale(1)";
            e.currentTarget.style.boxShadow = `0 4px 16px ${T.accent}55`;
          }}
        >
          +
        </button>
      </div>
    </>
  );
}

