                              width: "100%",
                              textAlign: "left",
                              padding: "10px 12px",
                              background: T.card,
                              border: `1px solid ${T.coachGreen}44`,
                              borderRadius: 10,
                              marginBottom: 6,
                              cursor: "pointer",
